"""."""
def con_str(strarr: list[str], k: int) -> str | None {
    n = len(strarr);
    res = "";
    if n == 0 or k > n or k <= 0 {
        return "";
    }
    for el in strarr {
        if len(el) > len(res) {
            res = el;
        }
    }
    for (idx, el) in enumerate(strarr) {
        if el == res {
            if len(strarr[idx:(idx + k)]) > len(strarr[:(k - idx)]) {
                return ''.join(strarr[idx:(idx + k)]);
            }
            return ''.join(strarr[:(idx - k)]);
        }
    }
    return None;
}
