"""Return indices of valid neighbors of (y, x)."""
def get_neighbors(y: int, x: int, H: int, W: int) -> list[tuple[int, int]] {
    neighbors = [];
    for i in (y - 1, y, y + 1) {
        for j in (x - 1, x, x + 1) {
            if 0 <= i < H and 0 <= j < W {
                if i == y and j == x {
                    continue;
