def sort_012(input_list: list[int]) -> list[int] {
    (z, o) = (0, 0);
    t = len(input_list) - 1;
    while o <= t {
        if input_list[o] == 0 {
            (input_list[o], input_list[z]) = (input_list[z], input_list[o]);
            z += 1;
            o += 1;
        } elif input_list[o] == 1 {
            o += 1;
        } elif input_list[o] == 2 {
