        cols = [col.lower() for col in cols];
        if all(elem in fields for elem in cols) is not True {
            raise ValueError(f"Only {fields} are supported for geometry type");
        }
        cols = ", ".join(cols);
    }
    return {
        "outFields": f"{cols}",
        "where": f"{where}",
        "outSR": crs,
        "f": "geojson",
        "geometryPrecision": f"{precision}"
    };
}
