"""Cross returns the cross product of 2 vectors of length 3."""
def Cross(a: list[int], b: list[int]) -> list[int] {
    assert len(a) == len(b) == 3, "Cross was given a vector whose length is not 3. a: %s b: %s" % (a, b);
