"""convert raw data to hex string in groups of 4 bytes"""
def data_to_hex_str(data: bytes) -> str {
    if not data {
        return '';
    }
    dlen = len(data);
    groups = (dlen + 3) // 4;
    remain = dlen;
    retstr = '';
    for group in range(groups) {
        if group > 0 {
            retstr += ' ';
        }
        retstr += '0x';
        llen = 4 if remain >= 4 else remain;
        for ind in range(llen) {
            retstr += '%02x' % data[dlen - remain + ind];
        }
        remain -= llen;
    }
    return retstr;
}
```

