    mixin: list[tuple[tuple[float, float], int]],
    trade_data: list[int],
    chain_length: float,
    sample_epoch: int
) -> list[list[tuple[tuple[float, float], int]]] {
    chain: list[tuple[tuple[float, float], int]] = [];
