import from typing { BinaryIO, TextIO }

"""Return True if file has non-ASCII characters (> 0x7F)."""
def is_binary_file(file_obj: BinaryIO | TextIO) -> bool {
    start = file_obj.tell();
    fbytes = file_obj.read(1024);
    file_obj.seek(start);
    is_str = isinstance(fbytes, str);
    for fbyte in fbytes {
        if is_str {
            code = ord(fbyte);
        } else {
            code = fbyte;
        }
        if code > 127 {
            return True;
        }
    }
    return False;
}
```

