    if hours > 0 {
        if len(s) > 0 {
            s += ' ';
        }
        s += f'{hours:d}h';
    }
    if minutes > 0 {
        if len(s) > 0 {
            s += ' ';
        }
        s += f'{minutes:d}min';
    }
    if seconds > 0 or len(s) == 0 {
        if len(s) > 0 {
            s += ' ';
        }
        s += f'{seconds:d}sec';
    }
    return s;
}
