"""Format a count and noun with optional pluralization and padding."""
def count_noun(
    number: int,
    noun: str,
    plural: str | None = None,
    pad_number: int | bool = False,
    pad_noun: bool = False
) -> str {
    if plural is None {
        plural = noun + "s";
    }
    noun_pad = "";
    if pad_noun {
        noun_pad = " " * (len(plural) - len(noun));
    }
    if pad_number {
        number_str = "%%%sd" % pad_number % number;
    } else {
        number_str = "%d" % number;
    }
    if number == 1 {
        return "%s %s%s" % (number_str, noun, noun_pad);
    }
    return "%s %s" % (number_str, plural);
}
```

