"""Classify record pairs by average similarity against a threshold in [0.0, 1.0]."""
def thresholdClassify(sim_vec_dict: dict[tuple[str, str], list[float]], sim_thres: float) -> tuple[set[tuple[str, str]], set[tuple[str, str]]] {
    assert sim_thres >= 0.0 and sim_thres <= 1.0, sim_thres;
    print('Similarity threshold based classification of %d record pairs' % len(sim_vec_dict));
    print('  Classification similarity threshold: %.3f' % sim_thres);
    class_match_set = set();
    class_nonmatch_set = set();
    for (rec_id_tuple, sim_vec) in sim_vec_dict.items() {
        sim_sum = float(sum(sim_vec));
        avr_sim = sim_sum / len(sim_vec);
        if avr_sim >= sim_thres {
            class_match_set.add(rec_id_tuple);
        } else {
            class_nonmatch_set.add(rec_id_tuple);
        }
    }
    print('  Classified %d record pairs as matches and %d as non-matches' % (len(class_match_set), len(class_nonmatch_set)));
    print('');
    return (class_match_set, class_nonmatch_set);
}
