def sort_player_scores(unsorted_scores: list[int], highest_possible_score: int) -> list[int] {
    tracker: dict[int, int] = {};
    sorted_scores: list[int] = [];
    if type(unsorted_scores) != list {
        raise TypeError(
            "The first argument for sort_player_scores must be of type list."
